def main() -> None:
    questions = []
    idx = 1
    for difficulty, bank in [("Easy", EASY), ("Medium", MEDIUM), ("Hard", HARD)]:
        for q, choices, answer, explanation, tags in bank:
            questions.append({
                "id": idx,
                **B,
                "difficulty": difficulty,
                "question": q,
                "choices": choices,
                "answer": answer,
                "explanation": explanation,
                "tags": tags,
            })
            idx += 1

    OUTPUT.parent.mkdir(parents=True, exist_ok=True)
    OUTPUT.write_text(json.dumps(questions, indent=2, ensure_ascii=False), encoding="utf-8")
    print(f"Wrote {len(questions)} questions to {OUTPUT}")


if __name__ == "__main__":
    main()
